function longestRise(nums) {
  const dp = nums.map(() => 1) //@init
  for (let i = 1; i < nums.length; i++) {
    for (let j = 0; j < i; j++) {
      if (nums[j] < nums[i]) dp[i] = Math.max(dp[i], dp[j] + 1) //@check
    }
  }
  return Math.max(...dp) //@done
}

